sited.script:

const baseUrl = "https://gimytw.cc";

function home_list_parse(url, html){
    const $ = cheerio.load(html);
    let list = [];
    $('div.layout-box').each(function() {
        const $$ = cheerio.load($(this).html());
        const group_name_raw = $$('div.box-title h3').text().trim();
        if (group_name_raw) {
            const group_name = gbk2big5.traditionalized(group_name_raw);
            $$('a.video-pic').each(function() {
                const link = cheerio(this);
                const videoUrl = link.attr('href');
                const name = link.attr('title');
                const logo = link.attr('data-original') || link.attr('data-src');
                if (videoUrl && name) {
                    list.push({
                        group: group_name,
                        url: baseUrl + videoUrl,
                        name: gbk2big5.traditionalized(name),
                        logo: logo ? (logo.startsWith('http') ? logo : baseUrl + logo) : null
                    });
                }
            });
        }
    });
    return JSON.stringify(list);
}

function list_parse(url, html){
    const $ = cheerio.load(html);
    let list = [];
    $('a.video-pic').each(function() {
        const link = cheerio(this);
        const videoUrl = link.attr('href');
        const name = link.attr('title');
        const logo = link.attr('data-original') || link.attr('data-src');
        if (videoUrl && name) {
            list.push({
                url: baseUrl + videoUrl,
                name: gbk2big5.traditionalized(name),
                logo: logo ? (logo.startsWith('http') ? logo : baseUrl + logo) : null
            });
        }
    });
    return JSON.stringify(list);
}

function search_parse(url, html){
    const $ = cheerio.load(html);
    let list = [];
    $('a.video-pic').each(function() {
        const link = cheerio(this);
        const videoUrl = link.attr('href');
        const name = link.attr('title');
        const logo = link.attr('data-original') || link.attr('data-src');
        if (videoUrl && name) {
            list.push({
                url: baseUrl + videoUrl,
                name: gbk2big5.traditionalized(name),
                logo: logo ? (logo.startsWith('http') ? logo : baseUrl + logo) : null
            });
        }
    });
    return JSON.stringify(list);
}

function book_parse(url, html) {
    const $ = cheerio.load(html);
    let sections = [];
    $('div.playlist').each(function() {
        const $$ = cheerio.load($(this).html());
        const group = $$('.gico, .box-title').text().trim() || "集數列表";
        $$('ul li a').each(function() {
            const episodeLink = cheerio(this);
            const episodeUrl = episodeLink.attr('href');
            if (episodeUrl) {
                sections.push({
                    group: gbk2big5.traditionalized(group),
                    name: gbk2big5.traditionalized(episodeLink.text().trim()),
                    url: baseUrl + episodeUrl
                });
            }
        });
    });

    let logoUrl = $('a.video-pic').attr('data-original') || $('a.video-pic').attr('data-src');
    const intro = $('span.details-content-default, span.details-content-all, div.item-desc').text().trim();

    const book = {
        name: gbk2big5.traditionalized($('h1').first().text().trim()),
        logo: logoUrl ? (logoUrl.startsWith('http') ? logoUrl : baseUrl + logoUrl) : null,
        intro: gbk2big5.traditionalized(intro.replace('線上看:', '').trim()),
        sections: sections
    };

    return JSON.stringify(book);
}

function section_parse(url, html) {
    return JSON.stringify({
        type: "webview",
        data: url
    });
}

sited.WebViewInjection:

javascript:(function() {
    function maximizePlayer() {
        try {
            var player = document.querySelector('iframe[name="p-frame"], .player_left, #zanpiancms_player, .player');
            if (player) {
                document.body.style.margin = '0';
                document.body.style.padding = '0';
                document.body.style.overflow = 'hidden';

                var current = player;
                while (current && current.tagName !== 'BODY') {
                    current.style.visibility = 'visible';
                    var siblings = Array.from(current.parentNode.children);
                    siblings.forEach(function(sibling) {
                        if (sibling !== current) {
                            sibling.style.display = 'none';
                        }
                    });
                    current = current.parentElement;
                }

                player.style.position = 'fixed';
                player.style.top = '0';
                player.style.left = '0';
                player.style.width = '100vw';
                player.style.height = '100vh';
                player.style.zIndex = '999999';
                return true;
            }
            return false;
        } catch (e) {
            return false;
        }
    }

    var attempts = 0;
    var intervalId = setInterval(function() {
        attempts++;
        if (maximizePlayer() || attempts >= 20) {
            clearInterval(intervalId);
        }
    }, 500);
})();
